<div class="grid gap-5 md:grid-cols-2"><label class="block"><span class="text-sm font-medium">Name</span><input name="name" required value="{{ old('name',$managedUser->name ?? '') }}" class="mt-1 w-full rounded-lg border-slate-300"></label><label class="block"><span class="text-sm font-medium">Email</span><input type="email" name="email" required value="{{ old('email',$managedUser->email ?? '') }}" class="mt-1 w-full rounded-lg border-slate-300"></label>@if(!isset($managedUser))<label class="block"><span class="text-sm font-medium">Temporary password</span><input type="password" name="password" required class="mt-1 w-full rounded-lg border-slate-300"></label><label class="block"><span class="text-sm font-medium">Confirm password</span><input type="password" name="password_confirmation" required class="mt-1 w-full rounded-lg border-slate-300"></label><label class="block"><span class="text-sm font-medium">Status</span><select name="status" class="mt-1 w-full rounded-lg border-slate-300"><option>ACTIVE</option><option>DISABLED</option></select></label>@endif</div><fieldset class="mt-6"><legend class="font-semibold">Roles</legend><div class="mt-2 flex flex-wrap gap-4">@foreach($roles as $role)<label class="flex items-center gap-2"><input type="checkbox" name="role_ids[]" value="{{ $role->id }}" @checked(in_array($role->id,$selectedRoles))><span>{{ $role->name }}</span></label>@endforeach</div></fieldset><fieldset class="mt-6"><legend class="font-semibold">Organizations</legend><p class="text-sm text-slate-500">Each selected role requires an active organization of the matching type.</p><div class="mt-2 grid gap-2 md:grid-cols-2">@foreach($organizations as $organization)<label class="flex items-center gap-2 rounded-lg border border-slate-200 p-3"><input type="checkbox" name="organization_ids[]" value="{{ $organization->id }}" @checked(in_array($organization->id,$selectedOrganizations))><span>{{ $organization->name }} <small class="text-slate-500">{{ $organization->type }}</small></span></label>@endforeach</div></fieldset><label class="mt-6 block"><span class="text-sm font-medium">Primary organization</span><select name="primary_organization_id" required class="mt-1 w-full rounded-lg border-slate-300"><option value="">Select primary organization</option>@foreach($organizations as $organization)<option value="{{ $organization->id }}" @selected($primary===$organization->id)>{{ $organization->name }} ({{ $organization->type }})</option>@endforeach</select></label><button class="mt-7 rounded-lg bg-[#075e63] px-5 py-2.5 font-semibold text-white">{{ isset($managedUser) ? 'Save changes' : 'Create user' }}</button>
